export type TokenCreate = {
    /**
     * RFC 3339 timestamp in the future. Omit for a token that never expires.
     */
    expires_at?: string | null;
    name: string;
    /**
     * Any of `memory:read`, `memory:write`, `vaults:admin`, `connectors`. Defaults
     * to all of them. Cannot exceed the creating credential's own scopes.
     */
    scopes?: Array<string> | null;
    /**
     * Restrict the token to one vault you belong to.
     */
    vault_id?: string | null;
};

export type TokenCreated = {
    expires_at?: string | null;
    id: string;
    name: string;
    scopes: Array<string>;
    /**
     * Shown once, never retrievable again.
     */
    token: string;
    vault_id?: string | null;
};

export type TokenOut = {
    created_at?: string | null;
    /**
     * `null` for a token that never expires.
     */
    expires_at?: string | null;
    id: string;
    last_used_at?: string | null;
    name: string;
    scopes: Array<string>;
    vault_id?: string | null;
};

export type TokenRename = {
    /**
     * The new name: trimmed, 1 to 80 characters.
     */
    name: string;
};

export type ToolUsageReport = {
    by_channel: Array<UsageByChannel>;
    by_credential: Array<UsageByCredential>;
    by_person: Array<UsageByPerson>;
    by_session: Array<UsageBySession>;
    by_tool: Array<UsageByTool>;
    hours: number;
    /**
     * `org`: everyone in the org (instance admin). `self`: the caller's own usage.
     */
    scope: string;
    series: Array<UsagePoint>;
    /**
     * `hour` for ranges up to 48 hours, `day` beyond.
     */
    series_step: string;
    since: string;
    totals: UsageCounts;
};

/**
 * Body of `POST /update/request` and `/update/check`.
 */
export type UpdateAck = {
    configured: boolean;
    /**
     * Present only when the updater is configured.
     */
    requested?: boolean | null;
};

/**
 * Documents the body of `GET /update/status`. The handler merges the on-disk
 * `status.json` written by `scripts/auto-update.sh` verbatim, so every field
 * except `configured` is absent when the updater is not configured.
 */
export type UpdateStatus = {
    applying?: boolean | null;
    checked_at?: string | null;
    configured: boolean;
    current_version?: string | null;
    error?: string | null;
    latest_version?: string | null;
    /**
     * While `applying`: what the updater is waiting on (e.g. a slow first boot it keeps retrying).
     */
    progress?: string | null;
    update_available?: boolean | null;
};

export type UsageByChannel = UsageCounts & {
    /**
     * `mcp`, `rest` or `chat`.
     */
    channel: string;
};

export type UsageByCredential = UsageCounts & {
    /**
     * The token's or OAuth client's id; empty for the browser session.
     */
    credential_id: string;
    email: string;
    /**
     * `session` (the signed-in browser), `token` (personal API token) or `oauth` (an OAuth client).
     */
    kind: string;
    /**
     * Token name, OAuth client name, or "Browser session".
     */
    label: string;
    user_id: string;
};

export type UsageByPerson = UsageCounts & {
    email: string;
    user_id: string;
};

export type UsageBySession = UsageCounts & {
    channel: string;
    email: string;
    /**
     * The `Mcp-Session-Id` the client sent, or the chat thread id.
     */
    session: string;
    user_id: string;
};

export type UsageByTool = UsageCounts & {
    read_only: boolean;
    tool: string;
};

/**
 * Calls, failed calls and mean duration of a group of tool calls.
 */
export type UsageCounts = {
    /**
     * Mean time a call took, in milliseconds.
     */
    avg_ms: number;
    calls: number;
    /**
     * Calls that ended in an error (a tool error value, a refused scope, or a failure).
     */
    errors: number;
};

export type UsagePoint = {
    /**
     * Start of the hour or day (UTC), RFC 3339.
     */
    bucket: string;
    calls: number;
    errors: number;
};

